package com.app.controller; import com.app.dto.SocietyNotificationDto;import com.app.security.UserPrincipal;import com.app.service.SocietyNotificationService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/society/notifications") @RequiredArgsConstructor public class SocietyNotificationController {private final SocietyNotificationService service;@GetMapping public List<SocietyNotificationDto> inbox(@AuthenticationPrincipal UserPrincipal p){return service.inbox(p.getAccountId(),p.getUserId());}@GetMapping("/unread-count") public Map<String,Long> unread(@AuthenticationPrincipal UserPrincipal p){return Map.of("count",service.unread(p.getAccountId(),p.getUserId()));}@PostMapping("/{id}/read") public SocietyNotificationDto read(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){return service.read(p.getAccountId(),p.getUserId(),id);}@PostMapping("/read-all") public void readAll(@AuthenticationPrincipal UserPrincipal p){service.readAll(p.getAccountId(),p.getUserId());}}
